import creditCardType from "credit-card-type";
import { CardType } from "@/types/payment";

export function detectCardType(cardNumber: string): CardType {
  const cleaned = cardNumber.replace(/\s/g, "").toLowerCase();
  if (!cleaned) return "unknown";

  // If it's already one of our types, return it
  if (["visa", "mastercard", "amex", "discover", "paypal"].includes(cleaned)) {
    return cleaned as CardType;
  }

  // If it has bullets but ends with a known type from a hacky string
  // (though it shouldn't happen with the current logic)
  if (cleaned.includes("•")) return "unknown";

  const results = creditCardType(cleaned);
  if (!results.length) return "unknown";

  const type = results[0].type;

  const map: Record<string, CardType> = {
    visa: "visa",
    mastercard: "mastercard",
    "american-express": "amex",
    discover: "discover",
  };

  return map[type] ?? "unknown";
}

export function formatCardNumber(value: string, type: CardType): string {
  const cleaned = value.replace(/\D/g, "");
  if (type === "amex") {
    return [cleaned.slice(0, 4), cleaned.slice(4, 10), cleaned.slice(10, 15)]
      .filter(Boolean)
      .join(" ");
  }
  return cleaned.slice(0, 16).replace(/(.{4})/g, "$1 ").trim();
}

export function maskCardNumber(cardNumber: string, type: CardType): string {
  const cleaned = cardNumber.replace(/\s/g, "");
  const maxLen = type === "amex" ? 15 : 16;
  const padded = cleaned.padEnd(maxLen, "•");
  if (type === "amex") {
    return `${padded.slice(0, 4)} ${padded.slice(4, 10)} ${padded.slice(10, 15)}`;
  }
  return `${padded.slice(0, 4)} ${padded.slice(4, 8)} ${padded.slice(8, 12)} ${padded.slice(12, 16)}`;
}
